-- Step 1: Change status column to TEXT to allow any value temporarily
ALTER TABLE `tasks` MODIFY COLUMN `status` TEXT NOT NULL DEFAULT 'pending';

-- Step 2: Update old status values to new ones
UPDATE tasks SET status = 'pending' WHERE status = 'todo';
UPDATE tasks SET status = 'published' WHERE status = 'done';

-- Step 3: Verify no old values remain
SELECT DISTINCT status FROM tasks;

